using QuestPDF.Fluent;
using QuestPDF.Helpers;
using QuestPDF.Infrastructure;

namespace BodegaDESAM.Services;

public sealed class SalidaPdfReportService
{
    const string Navy="#17324D",Blue="#276A93",Muted="#607080",Line="#D9E2E9",Stripe="#EDF4F8";
    public byte[] CreatePdf(Salida s,string? entrega)
    {
        QuestPDF.Settings.License=LicenseType.Community; var total=s.DetalleSalida.Sum(x=>(long)x.Cantidad);
        return Document.Create(d=>d.Page(p=>{p.Size(PageSizes.A4);p.Margin(32);p.DefaultTextStyle(x=>x.FontFamily("Arial").FontSize(9).FontColor("#1F2933"));p.Header().Element(c=>Header(c,s.Id));p.Content().Column(c=>{c.Spacing(14);c.Item().Element(x=>Metadata(x,s,entrega));c.Item().Element(x=>Detail(x,s));c.Item().AlignRight().Text($"TOTAL DESPACHADO: {total:N0} unidades").FontSize(10).Bold().FontColor(Navy);c.Item().Element(x=>Signatures(x,s.Solicitante,entrega));c.Item().Text("Este documento respalda la entrega física y la salida de existencias del inventario.").FontSize(7.5f).FontColor(Muted);});p.Footer().Element(Footer);})).GeneratePdf();
    }
    static void Header(IContainer c,int id)=>c.Column(x=>{x.Item().Background(Navy).Padding(14).Row(r=>{r.RelativeItem().Column(l=>{l.Item().Text("DESAM | GESTIÓN DE BODEGA").FontSize(9).SemiBold().FontColor("#CDE4F2");l.Item().PaddingTop(3).Text("COMPROBANTE DE SALIDA").FontSize(16).Bold().FontColor(Colors.White);l.Item().Text("Despacho de existencias").FontSize(8.5f).FontColor("#D7E5ED");});r.ConstantItem(120).AlignMiddle().AlignRight().Column(q=>{q.Item().Text("FOLIO").FontSize(7).SemiBold().FontColor("#CDE4F2");q.Item().Text($"N° {id:D6}").FontSize(14).Bold().FontColor(Colors.White);});});x.Item().Height(3).Background(Blue);});
    static void Metadata(IContainer c,Salida s,string? entrega)=>c.Table(t=>{t.ColumnsDefinition(x=>{x.RelativeColumn();x.RelativeColumn();x.RelativeColumn();});Cell(t,"FECHA DEL MOVIMIENTO",s.Fecha.ToString("dd/MM/yyyy"));Cell(t,"BODEGA DE ORIGEN",NameCode(s.Bodega?.Nombre,s.Bodega?.Codigo));Cell(t,"ESTABLECIMIENTO DESTINO",V(s.EStablecimiento?.Nombre));Cell(t,"SOLICITANTE",V(s.Solicitante));Cell(t,"ENTREGA",V(entrega));Cell(t,"OBSERVACIONES",V(s.Observacion));});
    static void Detail(IContainer c,Salida s)=>c.Column(x=>{x.Item().BorderLeft(3).BorderColor(Blue).PaddingLeft(7).Text("DETALLE Y TRAZABILIDAD DEL DESPACHO").FontSize(9).SemiBold().FontColor(Navy);x.Item().PaddingTop(5).Table(t=>{t.ColumnsDefinition(q=>{q.RelativeColumn(3.3f);q.RelativeColumn(3.7f);q.RelativeColumn(1.3f);});Head(t,"PRODUCTO");Head(t,"ORIGEN Y TRAZABILIDAD");Head(t,"CANT.",true);var i=0;foreach(var d in s.DetalleSalida.OrderBy(q=>q.Id)){var bg=i++%2==0?"#FFFFFF":Stripe;Body(t,bg,z=>{z.Item().Text(d.Producto?.Nombre??"Sin producto").SemiBold();z.Item().Text($"Categoría: {V(d.Producto?.CategoriaProducto?.Nombre)}").FontSize(7.5f).FontColor(Muted);z.Item().Text($"Marca / modelo: {V(d.Marca?.Nombre)} / {V(d.Modelo?.Nombre)}").FontSize(7.5f).FontColor(Muted);});Body(t,bg,z=>{z.Item().Text($"Lote: {V(d.Lote?.Codigo)} | Vence: {(d.DetalleEntrada?.FechaVencimiento??d.Lote?.FechaVencimiento)?.ToString("dd/MM/yyyy")??"-"}").FontSize(8);z.Item().Text($"Ubicación origen: {V(d.Ubicacion?.CodigoCompleto)}").FontSize(7.2f).FontColor(Muted);var o=d.DetalleEntrada?.Entrada;z.Item().Text(o is not null?$"Entrada origen: #{o.Id:D6} | Doc.: {V(o.NDocumento)} | Proveedor: {V(o.Proveedor?.Nombre)}":d.DetalleAjusteOrigen is not null?$"Ajuste origen: #{d.DetalleAjusteOrigen.id_ajuste:D6}":"Origen histórico no disponible").FontSize(7.2f).FontColor(Muted);var series=s.ProductoSeries.Where(q=>q.id_producto==d.id_producto&&!string.IsNullOrWhiteSpace(q.Serie)).Select(q=>q.Serie.Trim()).Distinct();z.Item().Text($"Series: {(series.Any()?string.Join(", ",series):"-")}").FontSize(7.2f).FontColor(Muted);});Body(t,bg,z=>z.Item().AlignRight().Text($"{d.Cantidad:N0}\nun.").SemiBold(),true);}});});
    static void Signatures(IContainer c,string? solicita,string? entrega)=>c.PaddingTop(8).Row(r=>{Sig(r.RelativeItem(),"Solicita / recibe",solicita);r.ConstantItem(42);Sig(r.RelativeItem(),"Entrega desde bodega",entrega);});static void Sig(IContainer c,string role,string? name)=>c.Column(x=>{x.Item().Text(role.ToUpperInvariant()).FontSize(7.5f).SemiBold().FontColor(Muted);x.Item().Height(30).BorderBottom(1).BorderColor(Muted);x.Item().PaddingTop(4).Text(V(name)).FontSize(8).SemiBold();x.Item().Text("Nombre, firma y fecha").FontSize(7).FontColor(Muted);});
    static void Footer(IContainer c)=>c.BorderTop(1).BorderColor(Line).PaddingTop(6).Row(r=>{r.RelativeItem().Text("Sistema de Gestión de Bodega DESAM").FontSize(7.5f).FontColor(Muted);r.AutoItem().Text(t=>{t.Span("Página ").FontSize(7.5f).FontColor(Muted);t.CurrentPageNumber().FontSize(7.5f).FontColor(Muted);t.Span(" de ").FontSize(7.5f).FontColor(Muted);t.TotalPages().FontSize(7.5f).FontColor(Muted);t.Span($" | Emitido {DateTime.Now:dd/MM/yyyy HH:mm}").FontSize(7.5f).FontColor(Muted);});});
    static void Cell(TableDescriptor t,string l,string v)=>t.Cell().Border(1).BorderColor(Line).Padding(7).Column(x=>{x.Item().Text(l).FontSize(6.8f).SemiBold().FontColor(Muted);x.Item().PaddingTop(2).Text(v).FontSize(8.5f).SemiBold();});static void Head(TableDescriptor t,string v,bool right=false){var c=t.Cell().Background(Navy).Padding(7);if(right)c=c.AlignRight();c.Text(v).FontSize(7.5f).SemiBold().FontColor(Colors.White);}static void Body(TableDescriptor t,string bg,Action<ColumnDescriptor> a,bool right=false){var c=t.Cell().Background(bg).BorderBottom(1).BorderColor(Line).Padding(7);if(right)c=c.AlignRight();c.Column(a);}static string V(string? s)=>string.IsNullOrWhiteSpace(s)?"-":s.Trim();static string NameCode(string? n,string? code)=>string.IsNullOrWhiteSpace(code)?V(n):$"{V(n)} ({code.Trim()})";
}
